public with sharing class CaseSurveyJob implements Queueable {

    private final List<Id> caseIds;

    /**
     * Convenience constructor for the one-case-per-job path.
     */
    public CaseSurveyJob(Id caseId) {
        this.caseIds = new List<Id>{ caseId };
    }

    /**
     * Process a chunk of cases. Used so the trigger can stay within the
     * per-transaction System.enqueueJob limit when many cases close at once.
     */
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = (caseIds == null) ? new List<Id>() : caseIds;
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id IN :caseIds
        ];

        List<Task> surveyTasks = new List<Task>();
        for (Case c : cases) {
            // Re-validate: a case could have been reopened or had its contact
            // removed between enqueue time and execution time.
            if (!c.IsClosed || c.ContactId == null) {
                continue;
            }

            surveyTasks.add(new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status       = 'Not Started'
            ));
        }

        if (!surveyTasks.isEmpty()) {
            // Partial-success insert: one bad row can't block the others in
            // this chunk. Each job is also its own transaction, so a whole
            // chunk failing can't affect the other jobs.
            List<Database.SaveResult> results = Database.insert(surveyTasks, false);
            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'CSAT survey task failed for WhatId ' + surveyTasks[i].WhatId +
                        ': ' + results[i].getErrors()
                    );
                }
            }
        }
    }
}
