public with sharing class RenewalReminderService {

    // Apex allows a maximum of 100 SingleEmailMessages per Messaging.sendEmail
    // call, and only 10 sendEmail invocations per transaction. Chunking by 100
    // keeps a 200-opportunity run within both limits.
    private static final Integer MESSAGES_PER_CALL = 100;

    /**
     * Sends a renewal-reminder email to the owner of each supplied opportunity.
     *
     * The job passes up to 200 opportunities per call.
     *
     * @param opportunityIds up to 200 opportunity Ids
     * @return the number of emails that were sent successfully
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Bulk query the data we need up front (never query inside the loop).
        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        // Build one message per opportunity.
        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
        for (Opportunity opp : opportunities) {
            if (opp.OwnerId == null) {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            // Required: users targeted by Id cannot save the email as an activity.
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody(
                'The opportunity "' + opp.Name + '" is due for renewal. ' +
                'Its close date is ' + String.valueOf(opp.CloseDate) + '. ' +
                'Please follow up with the customer.'
            );
            messages.add(email);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        Integer sentCount = 0;

        // Send in chunks so one failing message does not stop the rest
        // (allOrNone = false) and so we stay within the 10 sendEmail
        // invocations-per-transaction governor limit.
        for (Integer start = 0; start < messages.size(); start += MESSAGES_PER_CALL) {
            Integer theEnd = Math.min(start + MESSAGES_PER_CALL, messages.size());
            List<Messaging.SingleEmailMessage> chunk = new List<Messaging.SingleEmailMessage>();
            for (Integer i = start; i < theEnd; i++) {
                chunk.add(messages[i]);
            }

            try {
                List<Messaging.SendEmailResult> results = Messaging.sendEmail(chunk, false);
                if (results != null) {
                    for (Messaging.SendEmailResult res : results) {
                        if (res.isSuccess()) {
                            sentCount++;
                        }
                    }
                }
            } catch (Exception ex) {
                // Swallow so remaining chunks are still processed.
                System.debug(LoggingLevel.ERROR,
                    'Renewal reminder chunk failed: ' + ex.getMessage());
            }
        }

        return sentCount;
    }
}
